<script setup>
import { ref, onMounted } from "vue"

const telefono = "5585833421"

// ⏰ solo reloj
const reloj = ref("")

onMounted(() => {
  setInterval(() => {
    reloj.value = new Date().toLocaleTimeString()
  }, 1000)
})

// 🛒 carrito
const carrito = ref([])
const agregar = (p) => carrito.value.push(p)
const eliminar = (i) => carrito.value.splice(i, 1)

const total = () =>
  carrito.value.reduce((s, p) => s + p.precio, 0)

// 🚚 entrega
const tipoEntrega = ref("Sucursal")
const direccion = ref("")
const metodoPago = ref("Efectivo")

// 📍 mapa
const direccionCompleta =
  "Granada 130, Morelos, Cuauhtémoc, 06200 CDMX"

const abrirMapa = () => {
  window.open(
    "https://www.google.com/maps?q=Granada+130+CDMX",
    "_blank"
  )
}

/* 🍕 PERSONALIZACIÓN */
const ingredientesBase = ["Jamón", "Pepperoni", "Champiñones", "Piña", "Carne"]

const seleccionados = ref([...ingredientesBase])
const extraQueso = ref(false)
const orillaQueso = ref(false)

const toggleIngrediente = (ing) => {
  if (seleccionados.value.includes(ing)) {
    seleccionados.value = seleccionados.value.filter(i => i !== ing)
  } else {
    seleccionados.value.push(ing)
  }
}

// 🍕 agregar pizza personalizada
const agregarPersonalizada = (nombre) => {
  let precio = 120

  // ingredientes extra ($20 cada uno extra de base)
  let extras = seleccionados.value.length - ingredientesBase.length
  if (extras > 0) precio += extras * 20

  if (extraQueso.value) precio += 50
  if (orillaQueso.value) precio += 50

  carrito.value.push({
    nombre: `🍕 ${nombre} personalizada`,
    precio
  })
}

/* 🍕 PIZZAS */
const pizzas = [
  {
    nombre:"Inferno Pepperoni",
    desc:"Salsa picante volcánica con pepperoni doble 🔥",
    precio:120,
    img:"data:image/jpeg;base64,"
  },
  {
    nombre:"Hawaiana Cósmica",
    desc:"Piña tropical con jamón galáctico 🍍",
    precio:130,
    img:"https://images.unsplash.com/photo-1594007654729-407eedc4be65"
  },
  {
    nombre:"Mexicana Rebelde",
    desc:"Chorizo, jalapeño y actitud 🌶️",
    precio:140,
    img:"data:image/jpeg;base64,"
  },
  {
    nombre:"Galactic Supreme",
    desc:"Todo el universo en una pizza 🌌",
    precio:150,
    img:"https://images.unsplash.com/photo-1513104890138-7c749659a591"
  },
  {
    nombre:"4 Quesos Nebula",
    desc:"Explosión cremosa de quesos 🧀",
    precio:150,
    img:"https://images.unsplash.com/photo-1541745537411-b8046dc6d66c"
  },
  {
    nombre:"BBQ Cosmic",
    desc:"Pollo BBQ con humo espacial 🍖",
    precio:140,
    img:"https://lifeloveandgoodfood.com/wp-content/uploads/2026/02/BBQ-Chicken-Pizza-14-1200x1200-1.jpg"
  },
  {
    nombre:"Veggie Aurora",
    desc:"Verduras frescas del jardín galáctico 🥦",
    precio:110,
    img:"data:image/jpeg;base64,"
  },
  {
    nombre:"Carnívora Extrema",
    desc:"Carne, tocino y poder máximo 🥩",
    precio:160,
    img:"https://images.unsplash.com/photo-1565299624946-b28f40a0ae38"
  },
  {
    nombre:"Pesto Galaxy",
    desc:"Salsa verde del universo 🌿",
    precio:135,
    img:"https://images.unsplash.com/photo-1593560708920-61dd98c46a4e"
  },
  {
    nombre:"Marina Profunda",
    desc:"Camarones del océano infinito 🌊",
    precio:170,
    img:"data:image/jpeg;base64,"
  }
]

/* 🥤 BEBIDAS */
const bebidas = [
  { nombre:"Coca Cola", desc:"Refresco clásico intergaláctico", precio:30, img:"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRqYSkpQx0QEV8UPhMhi8A4jGTFzkObuNo4Uw&s" },
  { nombre:"Pepsi", desc:"Sabor intenso cósmico", precio:30, img:"https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcRNHnM2UM8bOIHrsLvpM7T19INfZ9J-7hgps__Oo5JhxkFcZQ0bNNZdVgbfIX9OVWDK5Qu0uENJh5g-liu2IyXREruVVDM2uQSTKALiYkUYJiIa_tnkrs-6sy0AW_GCkPL0qC7vR0r9UoOx&usqp=CAc" },
  { nombre:"Agua", desc:"Pureza del universo", precio:20, img:"https://encrypted-tbn2.gstatic.com/shopping?q=tbn:ANd9GcRj7HYBM53omSSKScVZl64RzHOrdaRi4CQpmOd9x9QZixOdjBYdH6PneZrRiZ1xlvrV-gwuptiveka9Sn9tf0JXtPG5ihcrFHXr78h2idXfNL1gZmVPq_GbNTgOQzVf-D1czIA4zy86bQ&usqp=CAc" },
  { nombre:"Jugo", desc:"Fruta fresca natural", precio:25, img:"https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcQZH9d3te-o9Ke7zECJimxl0v8nNBQD6-ubJ4IUyA7bugytH4HL1dOngfZkUIrBu82D-qC2UU_PK9gijUmInf6iXZ7XVYwjrpIMii5JfQ9udQKjKW0EaVGqlJJZ1Q5h-xICrMfCS80&usqp=CAc" },
