]

/* 📦 WHATSAPP */
const pedirTodo = () => {
  let msg = "🌌 Pedido Pizzería Elmos 🌌\n\n"

  carrito.value.forEach(p => {
    msg += `🍕 ${p.nombre} - $${p.precio}\n`
  })

  msg += `\n💰 Total: $${total()}`
  msg += `\n🚚 Entrega: ${tipoEntrega.value}`

  if (tipoEntrega.value === "Domicilio") {
    msg += `\n📍 Dirección: ${direccion.value}`
  }

  msg += `\n💳 Pago: ${metodoPago.value}`

  window.open(`https://wa.me/52${telefono}?text=${encodeURIComponent(msg)}`)
}
</script>

<template>
