        <p class="precio">${{ b.precio }}</p>
        <button @click="agregar(b)">Agregar</button>
      </div>
    </div>

    <!-- PERSONALIZACIÓN -->
    <h2>Personalización</h2>

    <div class="panel">
      <p>Ingredientes (clic para agregar/quitar):</p>

      <label v-for="ing in ingredientesBase" :key="ing">
        <input type="checkbox"
          :checked="seleccionados.includes(ing)"
          @change="toggleIngrediente(ing)">
        {{ ing }}
      </label>

      <label>
        <input type="checkbox" v-model="extraQueso">
        Extra queso (+$50)
      </label>

      <label>
        <input type="checkbox" v-model="orillaQueso">
        Orilla de queso (+$50)
      </label>
    </div>

    <!-- CARRITO -->
    <h2>🛒 Carrito</h2>

    <div v-for="(item,i) in carrito" :key="i">
      {{ item.nombre }} - ${{ item.precio }}
      <button @click="eliminar(i)">❌</button>
    </div>

    <h3>Total: ${{ total() }}</h3>

    <!-- ENTREGA -->
    <h2>🚚 Entrega</h2>

    <select v-model="tipoEntrega">
      <option>Sucursal</option>
      <option>Domicilio</option>
    </select>

    <input v-if="tipoEntrega==='Domicilio'"
      v-model="direccion"
      placeholder="Tu dirección">

    <!-- PAGO -->
    <h2>💳 Pago</h2>

    <select v-model="metodoPago">
      <option>Efectivo</option>
      <option>Tarjeta</option>
    </select>

    <!-- BOTON WHATSAPP -->
    <button class="whatsapp" @click="pedirTodo">
      Pedir por WhatsApp 📲
    </button>

    <!-- DIRECCIÓN + MAPA -->
    <h2>📍 Ubicación</h2>

    <div class="direccion" @click="abrirMapa">
      {{ direccionCompleta }} (clic para abrir)
    </div>

    <iframe
      class="mapa"
      src="https://www.google.com/maps?q=Granada+130+CDMX&output=embed">
    </iframe>

  </div>
